from itertools import combinations

# Generate K_12
n = 12
edges = list(combinations(range(n), 2))

# Check maximum independent set size
def max_independent_set_size(n, edges):
    # Build adjacency
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check all subsets
    max_size = 0
    for r in range(1, n+1):
        for subset in combinations(range(n), r):
            is_independent = True
            for i in range(len(subset)):
                for j in range(i+1, len(subset)):
                    if subset[j] in adj[subset[i]]:
                        is_independent = False
                        break
                if not is_independent:
                    break
            if is_independent:
                max_size = max(max_size, r)
    return max_size

# Check vertex connectivity
def vertex_connectivity(n, edges):
    # Build adjacency
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check if removing k vertices disconnects the graph
    from collections import deque

    def is_connected(remaining):
        if len(remaining) <= 1:
            return True
        remaining_set = set(remaining)
        start = remaining[0]
        visited = {start}
        queue = deque([start])
        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if neighbor in remaining_set and neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return len(visited) == len(remaining)

    # Find minimum k such that removing k vertices disconnects
    for k in range(1, n):
        for removed in combinations(range(n), k):
            remaining = [v for v in range(n) if v not in removed]
            if not is_connected(remaining):
                return k
    return n - 1

print(f"Number of edges: {len(edges)}")
print(f"Max independent set size: {max_independent_set_size(n, edges)}")
print(f"Vertex connectivity: {vertex_connectivity(n, edges)}")
